32	class GE_FUNC_DEV_VISIBILITY GE_FUNC_HOST_VISIBILITY Anchor : public std::enable_shared_from_this<Anchor> {
33	  friend class AnchorUtils;
34	
35	 public:
36	  using TYPE = const char *;
37	  template <class T>
38	  using Vistor = RangeVistor<T, std::shared_ptr<ConstAnchor>>;
39	
