44	  Anchor &operator=(Anchor &&) = delete;
45	  virtual ~Anchor();
46	
47	 protected:
48	  // Whether the two anchor is equal
49	  virtual bool Equal(const AnchorPtr anchor) const = 0;
50	  virtual bool IsTypeOf(const TYPE type) const;
51	  virtual bool IsTypeIdOf(const TypeId &type) const;
52	  virtual TYPE GetSelfType() const;
53	
54	 public:
55	  // Get all peer anchors connected to current anchor
