70	
71	  // Remove all links with the anchor
72	  void UnlinkAll() noexcept;
73	
74	  // Remove link with the given anchor
75	  graphStatus Unlink(const AnchorPtr &peer);
76	
77	  // insert node
78	  // this--old_peer ---> this--first_peer   second_peer--old_peer
79	  graphStatus Insert(const AnchorPtr &old_peer, const AnchorPtr &first_peer, const AnchorPtr &second_peer);
80	
81	  // Replace peer with new peer
82	  graphStatus ReplacePeer(const AnchorPtr &old_peer, const AnchorPtr &new_peer);
83	
84	  // Judge if the anchor is linked with the given anchor
85	  bool IsLinkedWith(const AnchorPtr &peer) const;
86	
87	  // Get anchor index of the node
88	  int32_t GetIdx() const;
89	
90	  // set anchor index of the node
91	  void SetIdx(const int32_t index);
92	
93	 protected:
94	  template <class T>
95	  static Anchor::TYPE TypeOf() {
96	    static_assert(std::is_base_of<Anchor, T>::value, "T must be a Anchor!");
97	    return METADEF_FUNCTION_IDENTIFIER;
98	  }
99	
100	 public:
101	  template <class T>
102	  static std::shared_ptr<T> DynamicAnchorCast(const AnchorPtr anchorPtr) {
103	    static_assert(std::is_base_of<Anchor, T>::value, "T must be a Anchor!");
104	    if ((anchorPtr == nullptr) || (!anchorPtr->IsTypeIdOf<T>())) {
105	      return nullptr;
106	    }
107	    return std::static_pointer_cast<T>(anchorPtr);
108	  }
109	
110	  template <class T>
111	  static T *DynamicAnchorPtrCast(Anchor *const anchor) {
112	    static_assert(std::is_base_of<Anchor, T>::value, "T must be a Anchor!");
113	    if ((anchor == nullptr) || (!anchor->IsTypeIdOf<T>())) {
114	      return nullptr;
115	    }
116	    return PtrToPtr<Anchor, T>(anchor);
117	  }
118	
119	  template <typename T>
120	  bool IsTypeOf() const {
121	    return IsTypeOf(TypeOf<T>());
122	  }
123	
124	  template <typename T>
125	  bool IsTypeIdOf() const {
126	    return IsTypeIdOf(GetTypeId<T>());
127	  }
128	
129	 protected:
130	  AnchorImplPtr impl_;
131	};
