199	    GELOGE(GRAPH_FAILED, "[Check][Param] peer anchor is invalid.");
200	    return GRAPH_FAILED;
201	  }
202	  GE_CHK_BOOL_RET_STATUS(impl_ != nullptr, GRAPH_FAILED, "[Check][Param] impl_ of anchor is nullptr");
203	  const auto it =
204	      std::find_if(impl_->peer_anchors_.begin(), impl_->peer_anchors_.end(), [peer](const std::weak_ptr<Anchor> &an) {
205	        const auto anchor = an.lock();
206	        return peer->Equal(anchor);
207	      });
208	  if (it == impl_->peer_anchors_.end()) {
209	    GELOGW("[Check][Param] Unlink failed , as this anchor is not connected to peer.");
210	    return GRAPH_FAILED;
211	  }
212	
213	  const auto it_peer = std::find_if(peer->impl_->peer_anchors_.begin(), peer->impl_->peer_anchors_.end(),
214	                                    [this](const std::weak_ptr<Anchor> &an) {
215	                                      const auto anchor = an.lock();
216	                                      return Equal(anchor);
217	                                    });
218	
219	  GE_CHK_BOOL_RET_STATUS(it_peer != peer->impl_->peer_anchors_.end(), GRAPH_FAILED,
220	                         "[Check][Param] peer(%s, %d) is not connected to this anchor(%s, %d)",
221	                         peer->GetOwnerNode()->GetName().c_str(), peer->GetIdx(),
222	                         this->GetOwnerNode()->GetName().c_str(), this->GetIdx());
223	  if ((this->GetOwnerNode() != nullptr) && (peer->GetOwnerNode() != nullptr)) {
224	    TRACE_GEN_RECORD(TraceManager::GetTraceHeader(), "delete", TraceManager::GetOutGraphName(),
225	                     this->GetOwnerNode()->GetName(), "output:" << this->GetIdx(), "", "",
226	                     peer->GetOwnerNode()->GetName() << ":input:" << peer->GetIdx());
227	  }
228	  (void)impl_->peer_anchors_.erase(it);
229	  (void)peer->impl_->peer_anchors_.erase(it_peer);
230	  return GRAPH_SUCCESS;
231	}
