233	graphStatus Anchor::Insert(const AnchorPtr &old_peer, const AnchorPtr &first_peer, const AnchorPtr &second_peer) {
234	  GE_CHECK_NOTNULL(old_peer);
235	  GE_CHECK_NOTNULL(first_peer);
236	  GE_CHECK_NOTNULL(second_peer);
237	  GE_CHECK_NOTNULL(impl_);
238	
239	  if (!IsSameType(old_peer->GetSelfType(), first_peer->GetSelfType())) {
240	    REPORT_INNER_ERR_MSG("E18888", "the type of old_peer[%s] and first_peer[%s] is not the same.",
241	                         old_peer->GetSelfType(), first_peer->GetSelfType());
242	    GELOGE(GRAPH_FAILED, "[Check][Param] the type of old_peer[%s] and first_peer[%s] is not the same.",
243	           old_peer->GetSelfType(), first_peer->GetSelfType());
244	    return GRAPH_FAILED;
245	  }
246	
247	  if (!IsSameType(second_peer->GetSelfType(), this->GetSelfType())) {
248	    REPORT_INNER_ERR_MSG("E18888", "the type of second_peer[%s] and current anchor[%s] is not the same.",
249	                         second_peer->GetSelfType(), this->GetSelfType());
250	    GELOGE(GRAPH_FAILED, "[Check][Param] the type of second_peer[%s] and current anchor[%s] is not the same.",
251	           second_peer->GetSelfType(), this->GetSelfType());
252	    return GRAPH_FAILED;
253	  }
254	
255	  if ((!CanAddPeer(first_peer)) || (!CanAddPeer(second_peer))) {
256	    REPORT_INNER_ERR_MSG("E18888", "first_peer[%s] or second_peer[%s] check failed", first_peer->GetSelfType(),
257	                         second_peer->GetSelfType());
258	    GELOGE(GRAPH_FAILED, "[Check][Param] first_peer[%s] or second_peer[%s] check failed", first_peer->GetSelfType(),
259	           second_peer->GetSelfType());
260	    return GRAPH_FAILED;
261	  }
262	
263	  const auto this_it = std::find_if(impl_->peer_anchors_.begin(), impl_->peer_anchors_.end(),
264	                                    [old_peer](const std::weak_ptr<Anchor> &an) {
265	                                      const auto anchor = an.lock();
266	                                      return old_peer->Equal(anchor);
267	                                    });
268	
269	  GE_CHK_BOOL_RET_STATUS(this_it != impl_->peer_anchors_.end(), GRAPH_FAILED,
270	                         "[Check][Param] this anchor(%s, %d) is not connected to old_peer(%s, %d)",
271	                         this->GetOwnerNode()->GetName().c_str(), this->GetIdx(),
272	                         old_peer->GetOwnerNode()->GetName().c_str(), old_peer->GetIdx());
273	
274	  const auto old_it = std::find_if(old_peer->impl_->peer_anchors_.begin(), old_peer->impl_->peer_anchors_.end(),
275	                                   [this](const std::weak_ptr<Anchor> &an) {
276	                                     const auto anchor = an.lock();
277	                                     return Equal(anchor);
278	                                   });
279	  GE_CHK_BOOL_RET_STATUS(old_it != old_peer->impl_->peer_anchors_.end(), GRAPH_FAILED,
280	                         "[Check][Param] old_peer(%s, %d) is not connected to this anchor(%s, %d)",
281	                         old_peer->GetOwnerNode()->GetName().c_str(), old_peer->GetIdx(),
282	                         this->GetOwnerNode()->GetName().c_str(), this->GetIdx());
283	  *this_it = first_peer;
284	  first_peer->impl_->peer_anchors_.push_back(shared_from_this());
285	  *old_it = second_peer;
286	  second_peer->impl_->peer_anchors_.push_back(old_peer);
287	  return GRAPH_SUCCESS;
288	}
