290	graphStatus Anchor::ReplacePeer(const AnchorPtr &old_peer, const AnchorPtr &new_peer) {
291	  GE_CHECK_NOTNULL(old_peer);
292	  GE_CHECK_NOTNULL(new_peer);
293	  GE_CHECK_NOTNULL(impl_);
294	  if (!IsSameType(old_peer->GetSelfType(), new_peer->GetSelfType())) {
295	    REPORT_INNER_ERR_MSG("E18888", "the type of old_peer[%s] and new_peer[%s] is not the same.",
296	                         old_peer->GetSelfType(), new_peer->GetSelfType());
297	    GELOGE(GRAPH_FAILED, "[Check][Param] the type of old_peer[%s] and new_peer[%s] is not the same.",
298	           old_peer->GetSelfType(), new_peer->GetSelfType());
299	    return GRAPH_FAILED;
300	  }
301	
302	  if (!CanAddPeer(new_peer)) {
303	    REPORT_INNER_ERR_MSG("E18888", "new_peer[%s] check failed.", new_peer->GetSelfType());
304	    GELOGE(GRAPH_FAILED, "[Check][Param] new_peer[%s] check failed.", new_peer->GetSelfType());
305	    return GRAPH_FAILED;
306	  }
307	
308	  const auto this_it = std::find_if(this->impl_->peer_anchors_.begin(), this->impl_->peer_anchors_.end(),
309	                                    [old_peer](const std::weak_ptr<Anchor> &an) {
310	                                      const auto anchor = an.lock();
311	                                      return old_peer->Equal(anchor);
312	                                    });
313	  if (this_it == this->impl_->peer_anchors_.end()) {
314	    GELOGE(GRAPH_FAILED, "[Check][Param] this anchor(%s, %d) is not connected to old_peer(%s, %d)",
315	           this->GetOwnerNode()->GetName().c_str(), this->GetIdx(), old_peer->GetOwnerNode()->GetName().c_str(),
316	           old_peer->GetIdx());
317	    return GRAPH_FAILED;
318	  }
319	
320	  const auto old_it = std::find_if(old_peer->impl_->peer_anchors_.begin(), old_peer->impl_->peer_anchors_.end(),
321	                                   [this](const std::weak_ptr<Anchor> &an) {
322	                                     const auto anchor = an.lock();
323	                                     return this->Equal(anchor);
324	                                   });
325	  *this_it = new_peer;
326	  (void)old_peer->impl_->peer_anchors_.erase(old_it);
327	  new_peer->impl_->peer_anchors_.push_back(shared_from_this());
328	  return GRAPH_SUCCESS;
329	}
