331	bool Anchor::IsLinkedWith(const AnchorPtr &peer) const {
332	  if (impl_ == nullptr) {
333	    GELOGE(GRAPH_FAILED, "[Check][Param] impl_ of anchor is nullptr.");
334	    return false;
335	  }
336	  const auto it =
337	      std::find_if(impl_->peer_anchors_.begin(), impl_->peer_anchors_.end(), [peer](const std::weak_ptr<Anchor> &an) {
338	        const auto anchor = an.lock();
339	        if (peer == nullptr) {
340	          GELOGE(GRAPH_FAILED, "[Check][Param] this old peer anchor is nullptr");
341	          return false;
342	        }
343	        return peer->Equal(anchor);
344	      });
345	  return (it != impl_->peer_anchors_.end());
346	}
